import java.util.*;

class Solution {
    public int[] degrees(int n, int[][] edges) {
        Map<Integer, List<Integer>> adj = new HashMap<>();
        for (int[] e : edges) {
            adj.computeIfAbsent(e[0], k -> new ArrayList<>()).add(e[1]);
            adj.computeIfAbsent(e[1], k -> new ArrayList<>()).add(e[0]);
        }
        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            res[i] = adj.getOrDefault(i, new ArrayList<>()).size();
        }
        return res;
    }
}

